import sqlite3,re,os,glob
DB='/tmp/claude-0/-home-user-guidebook/292c6e38-dad6-5791-8812-e5935ccdd833/scratchpad/gb.db'
con=sqlite3.connect(f'file:{DB}?mode=ro',uri=True)
cols={t:{r[1] for r in con.execute(f'pragma table_info("{t}")')} for (t,) in con.execute("select name from sqlite_master where type in ('table','view')")}
files=[f for pat in ('scripts/**/*.py','tools/*.py','schemas/*.py','skills/*.md','.github/workflows/*.yml','governance/*.yaml') for f in glob.glob(pat,recursive=True) if 'migrations' not in f and 'deprecated' not in f]
# Pattern 1: explicit table.column / alias-free "FROM <table> ... WHERE <col>" is hard; do dotted refs and SELECT-list scanning for the retired columns only.
retired={'specifications':['item_code','population_code'],'source_value_extractions':[],'evidence_sources':['author_display','first_author_last','authors','applicable_groups']}
hits=[]
for f in files:
    s=open(f,errors='ignore').read()
    for t,cs in retired.items():
        for c in cs:
            # a SQL region naming table t and column c within 300 chars
            for m in re.finditer(r'(?:FROM|UPDATE|INTO|JOIN)\s+"?%s"?\b'%t,s):
                seg=s[m.start():m.start()+400]
                if re.search(r'\b%s\b'%c,seg) and c not in cols[t]:
                    line=s[:m.start()].count('\n')+1
                    hits.append((f,line,t,c))
seen=set()
for h in hits:
    if h[:3] in seen: continue
    seen.add(h[:3]); print(h)
print("total distinct file/line/table hits:",len(seen))
